{"expression": "// Find and click the "Crypto" filter button
const allBtns = document.querySelectorAll('button, [role="tab"]');
let clicked = false;
allBtns.forEach(btn => {
  if (btn.innerText.trim() === 'Crypto' && !clicked) {
    btn.click();
    clicked = true;
  }
});
// Also try links
if (!clicked) {
  document.querySelectorAll('a, span[onclick]').forEach(el => {
    if (el.innerText.trim() === 'Crypto' && !clicked) {
      el.click();
      clicked = true;
    }
  });
}
JSON.stringify({clicked, totalButtonsScanned: allBtns.length, allTexts: [...allBtns].map(b => b.innerText.trim()).filter(t => t.length < 30)});"}

