{"expression": "// Get all GIPHY GIF page links with their GIF IDs
const allLinks = [...document.querySelectorAll('a[href*="/gifs/"]')];
const gifIds = allLinks.map(a => {
  const match = a.href.match(/\/gifs\/[^-]+-(.+)$/);
  return match ? match[1] : null;
}).filter(Boolean).slice(0, 15);
JSON.stringify({count: gifIds.length, ids: gifIds});"}

